+package com.example;
+
+import com.vaadin.flow.spring.annotation.VaadinSessionScope;
+import org.springframework.stereotype.Component;
+
+import java.io.Serializable;
+import java.util.ArrayList;
+import java.util.List;
+
+/** Messages belong to the user's session and survive route changes. */
+@Component
+@VaadinSessionScope
+public class SentMessages implements Serializable {
+    public record Message(String name, String email, String phone, String message) implements Serializable {}
+
+    private final List<Message> messages = new ArrayList<>();
+
+    public void add(Message message) {
+        messages.addFirst(message);
+    }
+
+    public List<Message> all() {
+        return List.copyOf(messages);
+    }
+}
